//! 🎟️ Genuine source stock admits, denies and closes the actual worker receiver.
use super::*;
use semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread;
struct Probe{value:Option<Box<u64>>}
impl InteractiveJob for Probe{
 fn step<'a>(&'a mut self,_:&mut StepContext<'_>,_:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{InteractiveJobStep::from_callback(Ok(None))}
 fn borrow_outcome<'a>(&'a self,_:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"birth probe has no semantic outcome"))}
 fn begin_close(&mut self){}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{if self.value.is_none(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}close_original_retained_effect_step(cx,RetirementDemand{release_bytes:std::mem::size_of::<u64>(),depth:1,..Default::default()},|_|{self.value.take();Ok::<_,ValueError>(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:std::mem::size_of::<u64>(),..Default::default()}))})}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(if self.value.is_some(){std::mem::size_of::<u64>()}else{0})}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.value.is_some()))}
 fn terminal_is_empty(&self)->bool{self.value.is_none()}
}
impl Drop for Probe{fn drop(&mut self){assert!(std::thread::panicking()||self.value.is_none(),"actual worker input lost without paid close")}}
fn clock()->Option<u64>{Some(0)}
fn law()->serde_json::Value{let law:serde_json::Value=serde_json::from_str(include_str!("../case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../case.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v)}law}
fn stock(law:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(law["stock"].clone()).unwrap()}
fn cleanup(admission:&mut WorkerJobSessionAdmission<Probe,BatchJobSession<Probe>>,output:&mut Option<BatchJobSession<Probe>>,caller:&mut OriginalJobFixtureCaller,law:&serde_json::Value){
 let g=stock(law);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if admission.terminal_is_empty(){break}caller.turn(g,|cx|admission.close_step(cx)).unwrap();}assert!(admission.terminal_is_empty());
 if let Some(session)=output.as_mut(){session.begin_close();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if session.terminal_is_empty(){break}caller.close_owner(g,session).unwrap();}assert!(session.terminal_is_empty());}
 assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(output.take())).1.released_bytes,0);
}
#[test]
fn original_worker_session_birth_keeps_both_real_null_frontiers_and_same_stock_output(){
 let law=law();let g=stock(&law);let _slots=super::super::worker_session_slots_exclusive();
 for (index,frontier)in law["nullFrontiers"].as_array().unwrap().iter().enumerate(){for(mode_index,mode)in law["nullResume"].as_array().unwrap().iter().enumerate(){
  let operation=OperationId(990_170+(index*2+mode_index)as u64);let generation=Generation(1);let mut caller=OriginalJobFixtureCaller::admit(operation,generation,g,clock,8000,law["maximumCpu"].as_u64().unwrap());let mut job=Some(Probe{value:Some(Box::new(37))});let pointer=job.as_ref().unwrap().value.as_deref().unwrap()as*const u64;
  let mut params=Some(BatchJobParams{operation,generation,cancel:caller.admit_alias(g),config:BatchDriveConfig{retained:g,site:"worker-birth-law",stage:InteractiveStage::InteractiveStep,fuel_per_step:law["quantum"].as_u64().unwrap(),step_budget_us:8000},now_us:clock});
  let mut admission=WorkerJobSessionAdmission::<Probe,BatchJobSession<Probe>>::new();let mut output=None;
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if admission.phase()==frontier.as_str().unwrap(){break}caller.turn(g,|cx|admission.advance(&mut job,&mut params,&mut output,cx)).unwrap();assert!(turn+1<law["maximumTurns"].as_u64().unwrap());}
  assert_eq!(admission.phase(),frontier.as_str().unwrap());let mut foreign=OriginalJobFixtureCaller::admit(operation,generation,g,clock,8000,law["maximumCpu"].as_u64().unwrap());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(g,|cx|{let work=cx.original_work_units_spent();let result=admission.advance(&mut job,&mut params,&mut output,cx);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["expected"]["foreignWork"].as_u64().unwrap()));result}));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert_eq!(admission.phase(),frontier.as_str().unwrap());assert!(output.is_none());foreign.retire(g);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let before=caller.cumulative_receipt();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(denied,|cx|{let work=cx.original_work_units_spent();let result=admission.advance(&mut job,&mut params,&mut output,cx);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["expected"]["deniedWork"].as_u64().unwrap()));result}));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert_eq!(caller.cumulative_receipt(),before);assert_eq!(admission.phase(),frontier.as_str().unwrap());assert!(output.is_none());}let capacity=caller.cumulative_receipt().retained_capacity_bytes;let before=caller.cumulative_receipt();
  let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(g,|cx|{let work=cx.original_work_units_spent();let(result,refused)=refuse_one_allocation_on_this_thread(||admission.advance(&mut job,&mut params,&mut output,cx));assert_eq!(refused,law["expected"]["nullAllocations"].as_u64().unwrap()as usize);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["expected"]["nullWork"].as_u64().unwrap()));result}));
  assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert_eq!(admission.phase(),frontier.as_str().unwrap());assert!(output.is_none());assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.cumulative_receipt().retained_capacity_bytes,capacity);
  if mode=="cancel"{assert!(job.is_none()&&params.is_none());cleanup(&mut admission,&mut output,&mut caller,&law);caller.retire(g);continue}
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if output.is_some(){break}caller.turn(g,|cx|admission.advance(&mut job,&mut params,&mut output,cx)).unwrap();assert!(turn+1<law["maximumTurns"].as_u64().unwrap());}
  assert!(admission.terminal_is_empty()&&job.is_none()&&params.is_none());let session=output.as_ref().unwrap();let authority=unsafe{(&*session.session.inner.authority.get()).as_ref().unwrap()};assert_eq!(authority.job().value.as_deref().unwrap()as*const u64,pointer);assert_eq!(serde_json::to_value(**authority.job().value.as_ref().unwrap()).unwrap(),serde_json::json!(37));cleanup(&mut admission,&mut output,&mut caller,&law);caller.retire(g);
 }}
}

#[test]
fn original_worker_session_quantum_one_keeps_paid_output_custody_and_denied_receiver(){
 let law=law();let g=stock(&law);let _slots=super::super::worker_session_slots_shared();let operation=OperationId(990_179);let generation=Generation(1);let mut caller=OriginalJobFixtureCaller::admit(operation,generation,g,clock,8000,law["maximumCpu"].as_u64().unwrap());let mut job=Some(Probe{value:Some(Box::new(79))});let mut params=Some(BatchJobParams{operation,generation,cancel:caller.admit_alias(g),config:BatchDriveConfig{retained:g,site:"worker-q1-law",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:8000},now_us:clock});let mut admission=WorkerJobSessionAdmission::<Probe,BatchJobSession<Probe>>::new();let mut output=None;
 for turn in 0..law["maximumTurns"].as_u64().unwrap(){if admission.phase()=="output"{break}caller.turn(g,|cx|{let work=cx.original_work_units_spent();let reserved=cx.reserved_return_work();let result=cx.with_original_work_loan(law["quantum"].as_u64().unwrap(),cx.original_absolute_deadline_us(),|cx|admission.advance(&mut job,&mut params,&mut output,cx));let actual=cx.original_work_units_spent()-work;let held=u128::from(cx.reserved_return_work()-reserved);assert!(actual>=held);assert!(actual-held<=u128::from(law["quantum"].as_u64().unwrap()));result}).unwrap();assert!(turn+1<law["maximumTurns"].as_u64().unwrap());}
 assert_eq!(admission.phase(),"output");assert!(output.is_none());let before=caller.cumulative_receipt();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(denied,|cx|admission.advance(&mut job,&mut params,&mut output,cx)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert_eq!(caller.cumulative_receipt(),before);assert_eq!(admission.phase(),"output");assert!(output.is_none());}
 caller.turn(g,|cx|{let work=cx.original_work_units_spent();let result=admission.advance(&mut job,&mut params,&mut output,cx);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["expected"]["handoffWork"].as_u64().unwrap()));result}).unwrap();assert!(admission.terminal_is_empty()&&output.is_some());assert_eq!(caller.receipt().copied_bytes,law["expected"]["ownershipCopyBytes"].as_u64().unwrap()as usize);cleanup(&mut admission,&mut output,&mut caller,&law);caller.retire(g);
}
